1: //! A ship module — a small authored tile patch that gets stamped into a hull.
2: //!
3: //! Like `Floor` it owns a decoded `TileGrid<TileKind>` cache, but it was written
4: //! later and never grew the scan helpers `Floor` has.
5: 
6: use crate::tilegrid::TileGrid;
7: use crate::TileKind;
8: 
9: pub struct Module {
10:     grid: TileGrid<TileKind>,
11: }
12: 
13: impl Module {
14:     pub fn new(w: u32, h: u32, tiles: Vec<TileKind>) -> Self {
15:         assert_eq!(tiles.len(), (w * h) as usize, "tile count must match dims");
16:         let mut grid = TileGrid::new_filled(w, h, TileKind::Empty);
17:         for (i, t) in tiles.into_iter().enumerate() {
18:             let (c, r) = ((i as u32 % w) as i32, (i as u32 / w) as i32);
19:             grid.set(c, r, t);
20:         }
21:         Module { grid }
22:     }
23: 
24:     pub fn width(&self) -> u32 {
25:         self.grid.width()
26:     }
27: 
28:     pub fn height(&self) -> u32 {
29:         self.grid.height()
30:     }
31: 
32:     /// `TileGrid::tile_at` takes `i32`, so we cast internally.
33:     pub fn tile_at(&self, col: u32, row: u32) -> TileKind {
34:         self.grid.tile_at(col as i32, row as i32)
35:     }
36: }

