{"content":"use crate::tilegrid::TileGrid;
use crate::tile_collide::{pos_to_tile_default, tile_center_default};

pub struct Floor {
    grid: TileGrid<TileKind>,
}

impl Floor {
    pub fn new(width: u32, height: u32) -> Self {
        Self {
            grid: TileGrid::new_filled(width, height, TileKind::Empty),
        }
    }

    pub fn find_first(&self, kind: TileKind) -> Option<(u32, u32)> {
        self.grid.find_first(kind)
    }

    pub fn tile_regions(&self, kind: TileKind) -> Vec<([u32; 2], [u32; 2])> {
        self.grid.tile_regions(kind)
    }

    pub fn tile_at(&self, col: i32, row: i32) -> TileKind {
        self.grid.tile_at(col, row)
    }

    pub fn set_tile(&mut self, col: i32, row: i32, kind: TileKind) {
        self.grid.set(col, row, kind);
    }
}

pub struct Module {
    grid: TileGrid<TileKind>,
}

impl Module {
    pub fn new(width: u32, height: u32) -> Self {
        Self {
            grid: TileGrid::new_filled(width, height, TileKind::Empty),
        }
    }

    pub fn find_first(&self, kind: TileKind) -> Option<(u32, u32)> {
        self.grid.find_first(kind)
    }

    pub fn tile_regions(&self, kind: TileKind) -> Vec<([u32; 2], [u32; 2])> {
        self.grid.tile_regions(kind)
    }

    pub fn tile_at(&self, col: i32, row: i32) -> TileKind {
        self.grid.tile_at(col, row)
    }

    pub fn set_tile(&mut self, col: i32, row: i32, kind: TileKind) {
        self.grid.set(col, row, kind);
    }
}","path":"src/module.rs","tool":"write_file"}

